WITH flattened AS (SELECT id, log_ts, level, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS attr_key, attr_value) SELECT CASE WHEN status_code >= 429 THEN 'LARGE' ELSE 'SMALL' END AS status_code_tier, DATE_TRUNC('HOUR', log_ts) AS hour_window, MIN(log_ts) AS started_at, SUM(CASE WHEN attr_key = 'version' THEN status_code ELSE 0 END) AS version_status_code, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS duration_min, GROUPING_ID() AS gid FROM flattened GROUP BY ROLLUP (CASE WHEN status_code >= 429 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('HOUR', log_ts));
